export const updateTeacherMe = async (teacherProfileUpdate: TeacherProfileUpdate, options?: RequestInit): Promise<Teacher> => {

  return customFetch<Teacher>(getUpdateTeacherMeUrl(),
  {
    ...options,
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      teacherProfileUpdate,)
  }
);}




export const getUpdateTeacherMeMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateTeacherMe>>, TError,{data: BodyType<TeacherProfileUpdate>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof updateTeacherMe>>, TError,{data: BodyType<TeacherProfileUpdate>}, TContext> => {

const mutationKey = ['updateTeacherMe'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof updateTeacherMe>>, {data: BodyType<TeacherProfileUpdate>}> = (props) => {
          const {data} = props ?? {};

          return  updateTeacherMe(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type UpdateTeacherMeMutationResult = NonNullable<Awaited<ReturnType<typeof updateTeacherMe>>>
    export type UpdateTeacherMeMutationBody = BodyType<TeacherProfileUpdate>
    export type UpdateTeacherMeMutationError = ErrorType<unknown>

    /**
 * @summary Update teacher profile
 */
export const useUpdateTeacherMe = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateTeacherMe>>, TError,{data: BodyType<TeacherProfileUpdate>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof updateTeacherMe>>,
        TError,
        {data: BodyType<TeacherProfileUpdate>},
        TContext
      > => {
      return useMutation(getUpdateTeacherMeMutationOptions(options));
    }

